style.css:
@-moz-document url-prefix("https://") {
/* Fondo negro */
  body {
    background-color: #000 !important;
    margin: 0;
    padding: 0;
    overflow: hidden !important;
    position: relative;
  }

  /* Contenedor de partículas */
  body::before {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
    background-color: #000;
  }

  /* Partículas (usando pseudo-elementos para generarlas dinámicamente) */
  body::after {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    background-image: radial-gradient(circle, rgba(255, 255, 255, 0.3) 15%, transparent 20%),
                      radial-gradient(circle, rgba(255, 255, 255, 0.2) 10%, transparent 15%),
                      radial-gradient(circle, rgba(255, 255, 255, 0.1) 5%, transparent 10%);
    background-size: 200px 200px, 300px 300px, 400px 400px;
    animation: moveParticles 10s linear infinite;
  }

  /* Animación del movimiento de partículas */
  @keyframes moveParticles {
    0% {
      background-position: 0 0, 50% 50%, 100% 100%;
    }
    100% {
      background-position: 0 100%, 50% 150%, 100% 200%;
    }
  }
}
